// Parse Brevo webhook payload
// Brevo sends events for: request, delivered, opened, clicked, soft_bounce, hard_bounce, invalid, deferred, complaint, unsubscribed, blocked
// Docs: https://developers.brevo.com/docs/transactional-webhooks

const input = $input.first().json;
const body = typeof input.body === 'string' ? JSON.parse(input.body) : input.body || input;

const eventType = body.event || '';
const email = body.email || '';
const timestamp = body.date || body.ts_event || new Date().toISOString();
const messageId = body['message-id'] || body.msg_id || '';
const tag = body.tag || '';
const campaignId = body.camp_id || body.campaign_id || '';

const emailEvent = {
  type: eventType,
  email: email,
  timestamp: typeof timestamp === 'number' ? new Date(timestamp * 1000).toISOString() : timestamp,
  message_id: messageId,
  campaign_id: campaignId,
  tag: tag,
  reason: '',
  shouldSuppress: false,
  details: ''
};

switch (eventType) {
  case 'hard_bounce':
    emailEvent.reason = 'hard_bounce';
    emailEvent.shouldSuppress = true;
    emailEvent.details = body.reason || 'Email address does not exist';
    break;

  case 'soft_bounce':
    emailEvent.reason = 'soft_bounce';
    emailEvent.shouldSuppress = false; // Soft bounces may recover
    emailEvent.details = body.reason || 'Temporary delivery failure';
    break;

  case 'invalid':
    emailEvent.reason = 'invalid';
    emailEvent.shouldSuppress = true;
    emailEvent.details = 'Invalid email format';
    break;

  case 'complaint':
  case 'spam':
    emailEvent.reason = 'spam';
    emailEvent.shouldSuppress = true;
    emailEvent.details = 'Marked as spam by recipient';
    break;

  case 'unsubscribed':
    emailEvent.reason = 'unsubscribe';
    emailEvent.shouldSuppress = true;
    emailEvent.details = body.link || 'User unsubscribed';
    break;

  case 'blocked':
    emailEvent.reason = 'blocked';
    emailEvent.shouldSuppress = true;
    emailEvent.details = body.reason || 'Email blocked by Brevo';
    break;

  default:
    // opened, clicked, delivered, request, deferred - don't suppress
    emailEvent.reason = 'other';
    emailEvent.shouldSuppress = false;
}

return { json: emailEvent };

